# ELIOT R35: one-shot patch to existing BG_VOICE_UPDATE.cmd; no new permanent updater.
# Only exact user-reported R32 updater is accepted. R33 was not executed by the user.
from __future__ import annotations
import hashlib,base64,gzip,os,sys,pathlib,tempfile,subprocess
from datetime import datetime,timezone
SOURCE_SHA="b1fa9aebb9fdf4d2214769d94fccb425b280e823594fe6f2901ee52a810a2c30"
ROUTE_SHA="7b42429e7c88b741cd5c98f3aed6a616f5441871730908c1ef9c1b74135a33b5"
ROUTE_B64=""
MARKER=b"# BGVOICE_V70_SINGLEFILE_INTEGRATION_END\r\n"
ANCHOR=b"        if '--eliot-r32-selftest' in sys.argv:\r\n"
FLAGS=(b"        if '--eliot-r35-selftest' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('selftest'))\r\n"
       b"        if '--eliot-r35-preflight' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('preflight'))\r\n"
       b"        if '--eliot-r35-stresscheck' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('stresscheck'))\r\n"
       b"        if '--eliot-r35-ruaccent-worker' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('ruaccent'))\r\n"
       b"        if '--eliot-r35-accentik-worker' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('accentik'))\r\n"
       b"        if '--eliot-r35-shtorm-worker' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('shtorm'))\r\n"
       b"        if '--eliot-r35-generate' in sys.argv:\r\n"
       b"            sys.exit(_eliot_r35_entry('generate'))\r\n")
EMBED=('import sys;p=sys.argv.pop(1);t=open(p,encoding="utf-8-sig").read();'
       'exec(compile(t.split(chr(10)+"#BGVOICE_PYTHON_START"+chr(10),1)[1],p,"exec"),'
       '{"__name__":"__main__","__file__":p})')
def sha(b):return hashlib.sha256(b).hexdigest()
def patch_exact(src):
    if sha(src)!=SOURCE_SHA:raise RuntimeError('UNKNOWN_ONE_UPDATER_SHA_HOLD '+sha(src))
    route=gzip.decompress(base64.b64decode(ROUTE_B64,validate=True))
    if sha(route)!=ROUTE_SHA or b'\r' in route:raise RuntimeError('ROUTE_SOURCE_INTEGRITY_HOLD')
    if src.count(MARKER)!=1 or src.count(ANCHOR)!=1 or b'_eliot_r35_entry' in src:raise RuntimeError('UPDATER_MARKER_HOLD')
    return src.replace(MARKER,route.replace(b'\n',b'\r\n')+b'\r\n'+MARKER,1).replace(ANCHOR,FLAGS+ANCHOR,1)
def is_exact_r35(src):
    route=gzip.decompress(base64.b64decode(ROUTE_B64,validate=True))
    if sha(route)!=ROUTE_SHA:raise RuntimeError('R35_ROUTE_SHA_FAIL')
    injection=route.replace(b'\n',b'\r\n')+b'\r\n'+MARKER
    if src.count(injection)!=1 or src.count(FLAGS+ANCHOR)!=1:return False
    recovered=src.replace(injection,MARKER,1).replace(FLAGS+ANCHOR,ANCHOR,1)
    return sha(recovered)==SOURCE_SHA and patch_exact(recovered)==src
def run(cmd,flag):
    env=os.environ.copy();env['PYTHONDONTWRITEBYTECODE']='1';env['HF_HUB_DISABLE_TELEMETRY']='1'
    return subprocess.call([sys.executable,'-u','-c',EMBED,str(cmd),flag],env=env)
def main():
    if os.name!='nt' or sys.version_info<(3,11):raise RuntimeError('WINDOWS_PYTHON_3_11_REQUIRED')
    home=pathlib.Path.home();folder=home/'Downloads'/'BG_VOICE_RU_TTS_READY'/'bg_voice_release_v2'
    cmd=folder/'BG_VOICE_UPDATE.cmd'
    if not cmd.is_file() or cmd.is_symlink() or folder.is_symlink():raise RuntimeError('ONE_UPDATER_NOT_FOUND_OR_LINK')
    src=cmd.read_bytes()
    if sha(src)==SOURCE_SHA:
        patched=patch_exact(src);expected=sha(patched)
        backdir=home/'Documents'/'BG_VOICE_RU'/'FULL_PRODUCTION'/'ELIOT_R35_UPDATER_BACKUPS'
        if backdir.is_symlink():raise RuntimeError('BACKUP_DIR_SYMLINK')
        backdir.mkdir(parents=True,exist_ok=True)
        bp=backdir/('BG_VOICE_UPDATE_PRE_R35_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'.bak')
        with bp.open('xb') as f:f.write(src);f.flush();os.fsync(f.fileno())
        if sha(bp.read_bytes())!=SOURCE_SHA:raise RuntimeError('BACKUP_INTEGRITY_HOLD')
        pending=folder/('BG_VOICE_UPDATE.cmd.R35_'+str(os.getpid())+'.pending')
        if pending.exists():raise RuntimeError('PENDING_UPDATER_EXISTS')
        try:
            with pending.open('xb') as f:f.write(patched);f.flush();os.fsync(f.fileno())
            if sha(pending.read_bytes())!=expected or sha(cmd.read_bytes())!=SOURCE_SHA:raise RuntimeError('UPDATER_CONCURRENT_CHANGED')
            os.replace(pending,cmd)
        finally:pending.unlink(missing_ok=True)
        print('ELIOT R35 exact R32 updater patched; SHA backup:',bp,flush=True)
    elif is_exact_r35(src):
        print('ELIOT R35 exact installed patch verified by reversible R32 SHA; resuming safely',flush=True)
    else:
        print('ELIOT R35 HOLD UNKNOWN UPDATER SHA',sha(src),'; no overwrite',flush=True)
        raise RuntimeError('NO_UPDATER_OVERWRITE_OF_UNKNOWN_VERSION')
    for f in ('--eliot-r35-selftest','--eliot-r35-preflight','--eliot-r35-stresscheck'):
        code=run(cmd,f)
        if code:
            print('ELIOT_R35_HOLD',f,'rc',code,'NO SYNTHESIS; see R35_STATUS.json if created',flush=True)
            return code
    print('ELIOT_R35_STRESS_CONSENSUS_PASS: 2 models, all multisyllabic words; beginning 2 Shtorm + 1 English-acoustic guide.',flush=True)
    result=run(cmd,'--eliot-r35-generate')
    if result==0:print('ELIOT_R35_CREATED: 3 audio candidate WAVs in one SEND_TO_CHATGPT_BG_VOICE_RU.zip; no game change',flush=True)
    else:print('ELIOT_R35_HOLD_GENERATION',result,'old WAVs intact',flush=True)
    return result
if __name__=='__main__':
    try:raise SystemExit(main())
    except KeyboardInterrupt:print('ELIOT R35 interrupted; originals intact');raise SystemExit(130)
    except Exception as exc:print('ELIOT R35 FAIL CLOSED',type(exc).__name__,str(exc)[:360],flush=True);raise SystemExit(2)
